import heapq

def f(x):
	budzet = 0
	ost_wrzucony = -1
	kolejka = []
	for i in range(0, il_bugow, x):
		bug = bugi[i][0]
		for j in range(ost_wrzucony + 1, il_stud):
			if studenci[j][1] >= bug:
				heapq.heappush(kolejka, studenci[j])
				ost_wrzucony = j
			else:
				break
		if len(kolejka) <= 0:
			return False
		st = heapq.heappop(kolejka)
		budzet += st[0]
		if budzet > il_kasy:
			return False
	return True

def fw(x):
	kolejka = []
	budzet = 0
	ost_wrzucony = -1
	kolejnosc = [-1 for x in range(il_bugow)]
	for i in range(0, il_bugow, x):
		bug = bugi[i][0]
		for j in range(ost_wrzucony + 1, il_stud):
			if studenci[j][1] >= bug:
				heapq.heappush(kolejka, studenci[j])
				ost_wrzucony = j
			else:
				break
		if len(kolejka) <= 0:
			return (False, [])
		st = heapq.heappop(kolejka)
		budzet += st[0]
		for c in range(i, min(i + x, il_bugow)):
			kolejnosc[bugi[c][1]] = st[2]
		if budzet > il_kasy:
			return (False, [])
	return (True, kolejnosc)

